+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const successMessage = document.getElementById('successMessage');
+
+// Create error message elements for each required field
+function createErrorElement(inputId, fieldName) {
+  const errorElement = document.createElement('p');
+  errorElement.id = `${inputId}-error`;
+  errorElement.className = 'error-message';
+  errorElement.textContent = `Error: ${fieldName} is required.`;
+  return errorElement;
+}
+
+// Set up error message containers after each required field
+[fullNameInput, emailInput].forEach((input) => {
+  const fieldName = input === fullNameInput ? 'Full name' : 'Email address';
+  const errorElement = createErrorElement(input.id, fieldName);
+  input.parentNode.appendChild(errorElement);
+});
+
+// Validate email format
+function isValidEmail(email) {
+  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+}
+
+// Validate phone format (optional, but if provided, check basic format)
+function isValidPhone(phone) {
+  if (!phone) return true; // Phone is optional
+  const phoneRegex = /^[\d\s\-().+]+$/;
+  return phoneRegex.test(phone) && phone.replace(/\D/g, '').length >= 10;
+}
+
+// Set validation state on input
+function setInputInvalid(input, isInvalid) {
+  input.setAttribute('aria-invalid', isInvalid);
+  const errorElement = document.getElementById(`${input.id}-error`);
+  if (errorElement) {
+    if (isInvalid) {
+      errorElement.classList.add('show');
+      const describedBy = input.getAttribute('aria-describedby') || '';
+      const errorId = `${input.id}-error`;
+      if (!describedBy.includes(errorId)) {
+        input.setAttribute(
+          'aria-describedby',
+          describedBy ? `${describedBy} ${errorId}` : errorId
+        );
+      }
+    } else {
+      errorElement.classList.remove('show');
+      const describedBy = input.getAttribute('aria-describedby') || '';
+      const errorId = `${input.id}-error`;
+      const newDescribedBy = describedBy
+        .split(' ')
+        .filter((id) => id !== errorId)
+        .join(' ');
+      if (newDescribedBy) {
+        input.setAttribute('aria-describedby', newDescribedBy);
+      } else {
+        input.removeAttribute('aria-describedby');
+      }
+    }
+  }
+}
+
+// Validate individual fields
+function validateField(input) {
+  const value = input.value.trim();
+
+  if (input === fullNameInput) {
+    const isInvalid = !value;
+    setInputInvalid(input, isInvalid);
+    return !isInvalid;
+  }
+
+  if (input === emailInput) {
+    const isInvalid = !value || !isValidEmail(value);
+    if (!value) {
+      document.getElementById('email-error').textContent = 'Error: Email address is required.';
+    } else if (!isValidEmail(value)) {
+      document.getElementById('email-error').textContent =
+        'Error: Enter a valid email like name@example.com.';
+    }
+    setInputInvalid(input, isInvalid);
+    return !isInvalid;
+  }
+
+  if (input === phoneInput) {
+    const isInvalid = value && !isValidPhone(value);
+    if (isInvalid) {
+      const errorElement = createErrorElement(input.id, 'Phone number');
+      errorElement.textContent = 'Error: Enter a valid phone number.';
+      if (!document.getElementById(`${input.id}-error`)) {
+        input.parentNode.appendChild(errorElement);
+      }
+    }
+    setInputInvalid(input, isInvalid);
+    return !isInvalid;
+  }
+
+  return true;
+}
+
+// Validate form on submit
+form.addEventListener('submit', (e) => {
+  e.preventDefault();
+  successMessage.hidden = true;
+
+  const fullNameValid = validateField(fullNameInput);
+  const emailValid = validateField(emailInput);
+  const phoneValid = validateField(phoneInput);
+
+  if (!fullNameValid || !emailValid || !phoneValid) {
+    // Focus first invalid field
+    if (!fullNameValid) {
+      fullNameInput.focus();
+    } else if (!emailValid) {
+      emailInput.focus();
+    } else if (!phoneValid) {
+      phoneInput.focus();
+    }
+    return;
+  }
+
+  // Form is valid - show success message
+  successMessage.hidden = false;
+  form.reset();
+  successMessage.focus();
+
+  // Clear validation states
+  [fullNameInput, emailInput, phoneInput].forEach((input) => {
+    setInputInvalid(input, false);
+  });
+});
+
+// Validate on blur
+[fullNameInput, emailInput, phoneInput].forEach((input) => {
+  input.addEventListener('blur', () => {
+    if (input.value.trim()) {
+      validateField(input);
+    }
+  });
+});
+
+// Clear error on input for fields that have been validated
+[fullNameInput, emailInput, phoneInput].forEach((input) => {
+  input.addEventListener('input', () => {
+    // Only clear error if the field was previously invalid
+    if (input.getAttribute('aria-invalid') === 'true') {
+      validateField(input);
+    }
+  });
+});
